<div class="<%= class_names("reaction", "reaction--deleteable": Current.user == reaction.user) %>"
     id="<%= dom_id(reaction) %>"
     title="<%= reaction.user.name %>"
     data-creator-id="<%= reaction.user_id %>"
     data-controller="reaction"
     data-reaction-creator-id-value="<%= reaction.user_id %>"
     data-action="click->reaction#toggle">
  <span class="reaction__avatar">
    <%= avatar_preview_tag reaction.user %>
  </span>

  <span class="<%= reaction.emoji_only? ? "txt-small txt-medium" : "txt-small" %>"><%= reaction.content %></span>

  <%= button_to [reaction.card, reaction.comment, reaction],
        method: :delete,
        class: "btn btn--circle borderless",
        form_class: "reaction__delete",
        aria: { label: "Remove reaction" },
        data: { action: "click->reaction#delete" } do %>
    <%= icon_tag "close" %>
  <% end %>
</div>

==> app/views/cards/comments/reactions/_reactions.html.erb <==
<div class="reactions" id="<%= dom_id(comment, :reactions) %>" data-controller="reactions">
  <div class="reactions__list">
    <% comment.reactions.each do |reaction| %>
      <%= render "cards/comments/reactions/reaction", reaction: reaction %>
    <% end %>
  </div>

  <% if comment.card.commentable? %>
    <button type="button" class="reactions__trigger btn btn--circle"
            aria-label="Add reaction"
            data-reactions-target="trigger"
            data-action="click->reactions#open">
      <%= image_tag "boost-color.svg", alt: "Add reaction" %>
    </button>

    <%= form_with model: [comment.card, comment, Reaction.new],
          class: "reaction reaction__form",
          html: { hidden: true },
          data: {
            reactions_target: "form",
            action: "keydown->reactions#keydown turbo:submit-end->reactions#submitEnd"
          } do |form| %>
      <label class="reaction__form-label">
        <%= form.text_field :content,
              class: "input reaction__input",
              maxlength: 16,
              required: true,
              autocomplete: "off",
              data: { reactions_target: "input" } %>
      </label>

      <button type="submit" class="btn btn--circle reaction__submit-btn" aria-label="Confirm reaction">
        <%= icon_tag "check" %>
      </button>

      <button type="button" class="btn btn--circle reaction__cancel-btn" aria-label="Cancel" data-action="click->reactions#close">
        <%= icon_tag "close" %>
      </button>
    <% end %>
  <% end %>
</div>

